import { useState, useEffect, useRef } from "react";
import { Link, useNavigate, useLocation } from "react-router-dom";
import { useAuth } from "../context/AuthContext";

function UnifiedNavbar() {
  const navigate         = useNavigate();
  const location         = useLocation();
  const { user, logout } = useAuth();
  const [menuOpen,      setMenuOpen]      = useState(false);
  const [unreadCount,   setUnreadCount]   = useState(0);
  const [newNotification, setNewNotification] = useState(null);
  const [showLogoutPopup, setShowLogoutPopup] = useState(false);
  const logoutPopupRef = useRef(null);
  const previousUnreadCount = useRef(null);

  const role   = user?.role?.toLowerCase() || "";
  const userId = user?.id || 0;

  // Fetch unread notification count
  useEffect(() => {
    let active = true;
    const fetchCount = async () => {
      try {
        const params = new URLSearchParams({ userId: String(userId), role });
        const res = await fetch(`http://localhost:5155/api/notification/unread-count?${params}`, { cache: "no-store" });
        if (res.ok) {
          const data = await res.json();
          if (!active) return;
          const nextCount = data.count || 0;
          const previousCount = previousUnreadCount.current;
          previousUnreadCount.current = nextCount;
          setUnreadCount(nextCount);

          if (previousCount !== null && nextCount > previousCount) {
            const notificationParams = new URLSearchParams({ userId: String(userId), role });
            const notificationRes = await fetch(`http://localhost:5155/api/notification?${notificationParams}`, { cache: "no-store" });
            if (notificationRes.ok && active) {
              const notifications = await notificationRes.json();
              const newestUnread = notifications.find(notification => !notification.isRead);
              if (newestUnread) setNewNotification(newestUnread);
            }
          }
        }
      } catch {}
    };
    if (userId) {
      fetchCount();
      const interval = setInterval(fetchCount, 5000);
      const refreshWhenVisible = () => {
        if (document.visibilityState === "visible") fetchCount();
      };
      window.addEventListener("focus", fetchCount);
      document.addEventListener("visibilitychange", refreshWhenVisible);
      return () => {
        active = false;
        clearInterval(interval);
        window.removeEventListener("focus", fetchCount);
        document.removeEventListener("visibilitychange", refreshWhenVisible);
      };
    }
    return () => { active = false; };
  }, [userId, role]);

  useEffect(() => {
    if (!showLogoutPopup) return undefined;

    const handlePointerDown = (event) => {
      if (!logoutPopupRef.current?.contains(event.target)) {
        setShowLogoutPopup(false);
      }
    };

    const handleEscape = (event) => {
      if (event.key === "Escape") {
        setShowLogoutPopup(false);
      }
    };

    document.addEventListener("mousedown", handlePointerDown);
    document.addEventListener("keydown", handleEscape);

    return () => {
      document.removeEventListener("mousedown", handlePointerDown);
      document.removeEventListener("keydown", handleEscape);
    };
  }, [showLogoutPopup]);

  const navLinks = {
    admin: [
      { to: "/admin",          label: "Dashboard"  },
      { to: "/students",       label: "Students"   },
      { to: "/users",          label: "Users"      },
      { to: "/edit-menu",      label: "Menu"       },
      { to: "/attendance",     label: "Attendance" },
      { to: "/leave-admin",    label: "Leaves"     },
      { to: "/feedback-admin", label: "Feedbacks"  },
      { to: "/item-requests",  label: "Requests"   },
      { to: "/payments",       label: "Payments"   },
      { to: "/food-prediction",label: "Food AI"    },
    ],
    staff: [
      { to: "/staff",         label: "Dashboard"  },
      { to: "/edit-menu",     label: "Menu"       },
      { to: "/today-menu",    label: "Today Menu" },
      { to: "/attendance",    label: "Attendance" },
      { to: "/leave",         label: "My Leaves"  },
      { to: "/item-request",  label: "Requests"   },
      { to: "/food-prediction",label: "Food AI"    },
    ],
    student: [
      { to: "/student",       label: "Dashboard"  },
      { to: "/today-menu",    label: "Menu"       },
      { to: "/attendance",    label: "Attendance" },
      { to: "/leave",         label: "Leave"      },
      { to: "/feedback",      label: "Feedback"   },
      { to: "/invoice",       label: "Pay Fees"   },
    ],
  };

  const links = navLinks[role] || [];

  const handleLogout = () => {
    setShowLogoutPopup(false);
    setMenuOpen(false);
    logout();
    navigate("/login");
  };

  const isActive = (path) => location.pathname === path;

  return (
    <nav className="navbar">
      <div className="navbar-container">

        {/* Logo */}
        <Link to={role === "admin" ? "/admin" : role === "staff" ? "/staff" : "/student"} className="navbar-logo">
          <img src="/logo_messhub.png" alt="MessHub" className="logo-icon" style={{ width: "40px", height: "40px", marginRight: "10px" }} />
          <span className="logo-text">MessHub</span>
        </Link>

        {/* Hamburger */}
        <button
          className={`hamburger ${menuOpen ? "active" : ""}`}
          onClick={() => setMenuOpen(!menuOpen)}
          aria-label="Toggle menu"
        >
          <span /><span /><span />
        </button>

        {/* Nav links */}
        <div className={`navbar-menu ${menuOpen ? "active" : ""}`}>
          <div className="navbar-links">
            {links.map(link => (
              <Link
                key={link.to}
                to={link.to}
                className={`nav-link ${isActive(link.to) ? "active" : ""}`}
                onClick={() => setMenuOpen(false)}
              >
                {link.label}
              </Link>
            ))}
          </div>

          {/* Right side — bell + user + logout */}
          <div className="navbar-actions">

            {/* Notification bell */}
            <Link
              to="/notifications"
              onClick={() => setMenuOpen(false)}
              style={{ position:"relative", display:"flex", alignItems:"center", justifyContent:"center", width:"36px", height:"36px", borderRadius:"var(--radius-full)", border:"1.5px solid var(--color-border)", background:"var(--color-surface)", color:"var(--color-text-secondary)", textDecoration:"none", transition:"all var(--transition-fast)" }}
            >
              <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round">
                <path d="M18 8A6 6 0 0 0 6 8c0 7-3 9-3 9h18s-3-2-3-9M13.73 21a2 2 0 0 1-3.46 0"/>
              </svg>
              {unreadCount > 0 && (
                <span style={{ position:"absolute", top:"-4px", right:"-4px", width:"18px", height:"18px", borderRadius:"var(--radius-full)", background:"var(--color-danger)", color:"white", fontSize:"9px", fontWeight:"var(--font-bold)", display:"flex", alignItems:"center", justifyContent:"center", border:"2px solid white" }}>
                  {unreadCount > 9 ? "9+" : unreadCount}
                </span>
              )}
            </Link>

            {/* User avatar + name */}
            {user && (
              <div style={{ display:"flex", alignItems:"center", gap:"var(--space-2)", position:"relative" }} ref={logoutPopupRef}>
                <div 
                  onClick={() => setShowLogoutPopup(!showLogoutPopup)}
                  style={{ 
                    width:"32px", 
                    height:"32px", 
                    borderRadius:"var(--radius-full)", 
                    background:"var(--color-brand-gradient)", 
                    display:"flex", 
                    alignItems:"center", 
                    justifyContent:"center", 
                    fontSize:"var(--text-xs)", 
                    fontWeight:"var(--font-bold)", 
                    color:"white", 
                    flexShrink:0,
                    cursor:"pointer",
                    transition:"all var(--transition-fast)"
                  }}
                  title="Click to show logout options"
                >
                  {(user.name || user.email || "U")[0].toUpperCase()}
                </div>
                <div style={{ display:"flex", flexDirection:"column" }}>
                  <span style={{ fontSize:"var(--text-xs)", fontWeight:"var(--font-semibold)", color:"var(--color-text-primary)", lineHeight:1.2 }}>
                    {user.name || user.email}
                  </span>
                  <span style={{ fontSize:"10px", color:"var(--color-text-tertiary)", textTransform:"capitalize" }}>
                    {user.role}
                  </span>
                </div>

                {/* Logout popup */}
                {showLogoutPopup && (
                  <div 
                    className="logout-popup" 
                    role="dialog" 
                    aria-label="Logout confirmation"
                    style={{
                      position:"absolute",
                      top:"100%",
                      right:0,
                      marginTop:"var(--space-2)",
                      background:"var(--color-surface)",
                      border:"1px solid var(--color-border)",
                      borderRadius:"var(--radius-lg)",
                      boxShadow:"var(--shadow-lg)",
                      zIndex:1000,
                      minWidth:"200px"
                    }}
                  >
                    <div className="logout-popup-top">
                      <div className="logout-popup-icon">
                        <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round">
                          <path d="M9 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h4"/>
                          <path d="M16 17l5-5-5-5"/>
                          <path d="M21 12H9"/>
                        </svg>
                      </div>
                      <div>
                        <div className="logout-popup-title">Log out now?</div>
                        <div className="logout-popup-text">Your current tab session will end.</div>
                      </div>
                    </div>

                    <div className="logout-popup-actions">
                      <button type="button" className="logout-popup-cancel" onClick={() => setShowLogoutPopup(false)}>
                        Cancel
                      </button>
                      <button type="button" className="logout-popup-confirm" onClick={handleLogout}>
                        Logout
                      </button>
                    </div>
                  </div>
                )}
              </div>
            )}
          </div>
        </div>

      </div>
      {newNotification && (
        <Link
          to="/notifications"
          onClick={() => setNewNotification(null)}
          role="status"
          style={{ position:"fixed", top:"76px", right:"20px", zIndex:1200, width:"min(360px, calc(100vw - 40px))", padding:"14px 16px", borderRadius:"14px", background:"var(--color-surface)", border:"1px solid var(--color-border)", borderLeft:"4px solid var(--color-danger)", boxShadow:"var(--shadow-lg)", color:"var(--color-text-primary)", textDecoration:"none", animation:"fadeIn 0.2s ease" }}
        >
          <div style={{ fontSize:"var(--text-xs)", color:"var(--color-danger)", fontWeight:"var(--font-bold)", textTransform:"uppercase", marginBottom:"4px" }}>New notification</div>
          <div style={{ fontSize:"var(--text-sm)", fontWeight:"var(--font-bold)", marginBottom:"3px" }}>{newNotification.title || "Notification"}</div>
          <div style={{ fontSize:"var(--text-xs)", color:"var(--color-text-secondary)", lineHeight:1.4 }}>{newNotification.message}</div>
          <button type="button" aria-label="Dismiss notification alert" onClick={event => { event.preventDefault(); event.stopPropagation(); setNewNotification(null); }} style={{ position:"absolute", top:"8px", right:"10px", border:0, background:"transparent", color:"var(--color-text-tertiary)", fontSize:"18px", cursor:"pointer" }}>×</button>
        </Link>
      )}
    </nav>
  );
}

export default UnifiedNavbar;
